            if (c + 1 < m) neigh[v].push_back(id(r, c + 1));
        }
    }

    int best = 0;
    int totalMasks = 1 << N;

    // For each subset of empty cells
    for (int mask = 0; mask < totalMasks; ++mask) {
        int emptyCount = __builtin_popcount(mask);
