    function<void(int)> dfs = [&](int v) {
        if (v == N) {
            int occupied = 0;
            for (int i = 0; i < N; ++i)
                if (cnt[i] > 0) ++occupied;
            maxFree = max(maxFree, N - occupied);
            return;
        }
