int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    if (!(cin >> n >> m)) return 0;
    int N = n * m;
    vector<pair<int,int>> cells;
    cells.reserve(N);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            cells.push_back({i, j});

    auto inside = [&](int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < m;
    };

    int totalMasks = 1 << N;
    vector<int> best(totalMasks, -1);
    best[0] = 0;
    int answer = 0;

    for (int mask = 0; mask < totalMasks; ++mask) {
        if (best[mask] < 0) continue;
        int used = best[mask];
        if (used == N) continue;
        int idx = __builtin_ctz(~mask & (totalMasks - 1));
        auto [x, y] = cells[idx];

        // stay
        int nx = x, ny = y;
        int id = nx * m + ny;
        int nmask = mask | (1 << id);
        if (best[nmask] < used + 1) best[nmask] = used + 1;

        // directions
        const int dx[4] = {0, 0, 1, -1};
        const int dy[4] = {1, -1, 0, 0};
        for (int d = 0; d < 4; ++d) {
            nx = x + dx[d];
            ny = y + dy[d];
            if (!inside(nx, ny)) continue;
            id = nx * m + ny;
            nmask = mask | (1 << id);
            if (best[nmask] < used + 1) best[nmask] = used + 1;
        }
    }

    for (int mask = 0; mask < totalMasks; ++mask)
        if (best[mask] == N)
            answer = max(answer, N - __builtin_popcount(mask));

    cout << answer << '\n';
    return 0;
}

