int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    if (!(cin >> n >> m)) return 0;
    int N = n * m;
    vector<pair<int,int>> cells;
    cells.reserve(N);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            cells.push_back({i, j});

    auto inb = [&](int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < m;
    };

    vector<vector<int>> adj(N);
    for (int i = 0; i < N; ++i) {
        auto [x, y] = cells[i];
        vector<pair<int,int>> dests;
        dests.push_back({x, y});
        if (inb(x-1, y)) dests.push_back({x-1, y});
        if (inb(x+1, y)) dests.push_back({x+1, y});
        if (inb(x, y-1)) dests.push_back({x, y-1});
        if (inb(x, y+1)) dests.push_back({x, y+1});
        for (auto &d : dests) {
            int j = d.first * m + d.second;
            adj[i].push_back(j);
        }
    }

    int best = 0;
    vector<int> cnt(N);
    vector<int> choice(N);
    function<void(int,int)> dfs = [&](int idx, int used) {
        if (idx == N) {
            best = max(best, N - used);
            return;
        }
        if (N - idx + (N - used) <= best) return;
        for (int d : adj[idx]) {
            bool wasZero = (cnt[d] == 0);
            cnt[d]++;
            choice[idx] = d;
            dfs(idx + 1, used + (wasZero ? 1 : 0));
            cnt[d]--;
        }
    };

    dfs(0, 0);
    cout << best << "\n";
    return 0;
}

