    if (!(cin >> n >> m)) return 0;
    int N = n * m;

    // Map (i,j) to index
    auto id = [m](int i, int j) { return i * m + j; };

    // Precompute neighbors for each cell
    vector<vector<int>> neighbors(N);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int v = id(i, j);
            neighbors[v].push_back(v); // stay
            if (i > 0) neighbors[v].push_back(id(i - 1, j));
            if (i + 1 < n) neighbors[v].push_back(id(i + 1, j));
            if (j > 0) neighbors[v].push_back(id(i, j - 1));
            if (j + 1 < m) neighbors[v].push_back(id(i, j + 1));
        }
    }

    int maxFree = 0;
    int totalMasks = 1 << N;

    // Precompute for each cell its bit mask
    vector<int> cellMask(N);
    for (int i = 0; i < N; ++i) cellMask[i] = 1 << i;

    for (int mask = 0; mask < totalMasks; ++mask) {
        int freeCells = 0;
        for (int v = 0; v < N; ++v) {
            if (mask & cellMask[v]) continue; // already occupied
            bool canBeFree = true;
            for (int u = 0; u < N && canBeFree; ++u) {
                if (mask & cellMask[u]) continue; // u already assigned to some target
                // Check if u can move to v
                bool canMove = false;
                for (int t : neighbors[u]) {
                    if (t == v) {
                        canMove = true;
                        break;
                    }
                }
                if (!canMove) {
                    canBeFree = false;
                }
            }
            if (canBeFree) ++freeCells;
        }
        if (freeCells > maxFree) maxFree = freeCells;
    }

    cout << maxFree << '\n';
    return 0;
}

